import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCar } from '../services/carService';
import LoanCalculator from '../components/LoanCalculator';
import TestDriveForm from '../components/TestDriveForm';
import { motion } from 'framer-motion';

const CarDetailPage = () => {
  const { id } = useParams();
  const [car, setCar] = useState(null);

  useEffect(() => {
    getCar(id).then(res => setCar(res.data)).catch(console.error);
  }, [id]);

  if (!car) return <div>Загрузка...</div>;

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ maxWidth: 1200, margin: '2rem auto', padding: '0 2rem' }}>
      <div style={{ display: 'flex', gap: '3rem', flexWrap: 'wrap', marginBottom: '3rem' }}>
        <motion.div whileHover={{ scale: 1.02 }} style={{ flex: '1 1 500px', borderRadius: '20px', overflow: 'hidden', boxShadow: '0 15px 30px rgba(0,0,0,0.1)' }}>
          <img src={car.image_url} alt={car.model} style={{ width: '100%', height: '400px', objectFit: 'cover' }} />
        </motion.div>
        <div style={{ flex: '1 1 400px' }}>
          <h1 style={{ fontFamily: "'Playfair Display', serif", fontSize: '2.8rem', marginBottom: '1rem' }}>
            {car.brand} {car.model}
          </h1>
          <p style={{ color: '#666', marginBottom: '1rem' }}>{car.description}</p>
          <p style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--primary)' }}>
            {car.price.toLocaleString()} ₽
          </p>
          <TestDriveForm carId={car.id} />
        </div>
      </div>
      <LoanCalculator carId={car.id} carPrice={car.price} />
    </motion.div>
  );
};

export default CarDetailPage;
